package main
import("encoding/json";"log";"net/http";"runtime";"github.com/Mairaelefante/go-collision-anomaly-detector/internal/core")
func main(){d:=core.New();jobs:=make(chan core.Event,2048);for i:=0;i<runtime.NumCPU();i++{go func(){for e:=range jobs{d.Process(e)}}()};m:=http.NewServeMux();m.HandleFunc("GET /health",func(w http.ResponseWriter,r *http.Request){json.NewEncoder(w).Encode(map[string]string{"status":"ok"})});m.HandleFunc("POST /events",func(w http.ResponseWriter,r *http.Request){var e core.Event;if json.NewDecoder(r.Body).Decode(&e)!=nil||e.EventID==""{http.Error(w,"invalid event",400);return};select{case jobs<-e:w.WriteHeader(202);default:http.Error(w,"queue full",503)}});m.HandleFunc("GET /stats",func(w http.ResponseWriter,r *http.Request){json.NewEncoder(w).Encode(d.Stats())});m.HandleFunc("GET /anomalies",func(w http.ResponseWriter,r *http.Request){json.NewEncoder(w).Encode(d.Anomalies())});log.Println("http://localhost:8080");log.Fatal(http.ListenAndServe(":8080",m))}

